function findCardBody(title){const heading=$$('#screen h2,#screen h3').find(h=>h.textContent.trim()===title);if(!heading)return null;let parent=heading.parentElement;for(let i=0;parent&&i<4;i++,parent=parent.parentElement){if(parent.className.includes('rounded')&&parent.querySelectorAll('h2,h3').length===1){let body=parent.querySelector('[data-feed]');if(!body){body=el('div');body.dataset.feed='';body.style.minHeight='260px';const header=heading.parentElement;const children=[...parent.children];for(const child of children){if(child===header||child.contains(heading))continue;child.remove();}parent.append(body);}return body;}}return null;}
