 for(const p of points){const coords=[Number(p.latitude),Number(p.longitude)];bounds.push(coords);const marker=mapVehicleMarker(coords,p,Number(p.active_alerts)>0).addTo(map);const info=el('div');info.append(el('strong',p.plate_number||'Position '+p.id),el('p',currentSpeed(p)),el('p','Ignition: '+ignitionLabel(p)),el('p',date(p.gps_time)));marker.bindPopup(info);binding.markers.set(String(p.id),marker);if(p.plate_number)marker.bindTooltip(p.plate_number,{permanent:true,direction:'top'});}
