function toggleReplay(){if(replay.frame){stopReplay();return;}if(replay.points.length<2){toast('Pilih kendaraan dan rentang yang memiliki sedikitnya dua posisi GPS valid.');return;}if(replay.time>=replay.end)replay.time=replay.start;function frame(now){if(replay.last!=null)replay.time=Math.min(replay.end,replay.time+Math.min(250,now-replay.last)*replay.rate);replay.last=now;renderReplay();if(replay.time<replay.end)replay.frame=requestAnimationFrame(frame);else stopReplay();}replay.frame=requestAnimationFrame(frame);}
