 const gateway=el('p','GPS gateway: pilih sensor untuk melihat gateway yang melaporkannya.');gateway.style.cssText='grid-column:1/-1;font-size:12px;color:#434655';$('#fields').append(gateway);
 sensor.onchange=()=>{const item=options.sensors.find(v=>String(v.id)===sensor.value);gateway.textContent=item?'GPS gateway: '+item.gateway_identifier+' · Terakhir diterima '+date(item.last_received_at)+' · Status sensor '+(item.status||'N/A'):'Pilih sensor.';};
 if(!options.sensors.length)$('#form-error').textContent='Belum ada sensor aktif yang terdeteksi server dan bebas dari kendaraan lain. Aktifkan sensor/GPS, lalu tunggu laporan perangkat masuk.';
