// Calendar dates represent entire WIB days regardless of the browser's timezone.
function tripDateBounds(fromDate,toDate){
 const valid=value=>/^\d{4}-\d{2}-\d{2}$/.test(value)&&!Number.isNaN(Date.parse(value+'T00:00:00+07:00'))&&new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Jakarta',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value+'T00:00:00+07:00'))===value;
 if(!valid(fromDate)||!valid(toDate))throw new Error('Pilih tanggal mulai dan tanggal selesai yang valid.');
 const from=new Date(fromDate+'T00:00:00.000+07:00'),to=new Date(toDate+'T23:59:59.999+07:00');
 if(to<from)throw new Error('Tanggal selesai tidak boleh sebelum tanggal mulai.');
 if(to-from>=366*86400000)throw new Error('Rentang tanggal maksimal 366 hari.');
 return {from:from.toISOString(),to:to.toISOString()};
}
function bindTripDateRange(){
 const screen=$('#screen');const calendar=[...screen.querySelectorAll('.material-symbols-outlined')].find(n=>n.textContent.trim()==='calendar_today');
 const original=calendar?.parentElement;const form=el('form');form.dataset.tripDateRange='';form.className='stitch-trip-date-range';
 const icon=el('span','date_range','material-symbols-outlined');icon.setAttribute('aria-hidden','true');form.append(icon);
 for(const [name,title]of [['from','Dari'],['to','Sampai']]){const labelNode=el('label',title);const input=el('input');input.type='date';input.name=name;input.required=true;input.value=tripDateSelection[name];input.setAttribute('aria-label',name==='from'?'Tanggal mulai riwayat':'Tanggal selesai riwayat');labelNode.append(input);form.append(labelNode);}
 const submit=el('button','Terapkan');submit.type='submit';form.append(submit);form.append(el('span','WIB','stitch-range-timezone'));const error=el('span','','stitch-range-error');error.setAttribute('role','alert');form.append(error);
 form.onsubmit=async event=>{event.preventDefault();error.textContent='';try{const from=form.elements.namedItem('from').value,to=form.elements.namedItem('to').value;const range=tripDateBounds(from,to);tripDateSelection={from,to};filters.from=range.from;filters.to=range.to;cursor=null;history=[];stopReplay();submit.disabled=true;await load();}catch(e){error.textContent=e.message;}finally{submit.disabled=false;}};
 if(original&&original!==screen)original.replaceWith(form);else{const host=screen.querySelector('h1')?.parentElement||screen.firstElementChild;host?.prepend(form);}
}

async function connectGPS(row){
 try{
  const choices=[];
  let next=null;
  do{
   const params=new URLSearchParams({limit:'200'});if(next)params.set('cursor',next);
   const result=await api('vehicles?'+params);choices.push(...result.data);next=result.page?.has_more?result.page.next_cursor:null;
  }while(next);
  const source=choices.find(v=>String(v.id)===String(row.vehicle_id));
  const gps=row.identifier||'GPS terpilih';
  const form=el('form',undefined,'stitch-setup-form');
  const field=el('label','Kendaraan tujuan'),select=el('select');select.name='vehicle_id';select.required=true;select.append(new Option('Pilih kendaraan',''));
  for(const v of choices)if(String(v.id)!==String(row.vehicle_id))select.append(new Option(vehicleIdentity(v)+(v.device_identifier?' · GPS '+v.device_identifier:''),String(v.id)));
  field.append(select);form.append(el('p',gps+' saat ini · '+(vehicleIdentity(source||row)||'Belum terhubung')),field);
  const preview=el('div',undefined,'device-edit-identity');preview.hidden=true;preview.setAttribute('aria-live','polite');
  const error=el('p','','stitch-error');error.setAttribute('role','alert');
  const actions=el('div',undefined,'stitch-setup-actions');
  const cancel=el('button','Batal'),save=el('button','Hubungkan GPS','stitch-setup-primary');
  cancel.type='button';cancel.onclick=()=>$('#inspector').close();save.type='submit';save.disabled=true;
  actions.append(cancel,save);form.append(preview,error,actions);
  const target=()=>choices.find(v=>String(v.id)===select.value);
  const update=()=>{
   const dest=target();
   preview.hidden=!dest;preview.replaceChildren();save.disabled=!dest||!!(dest.device_id&&!source)||!!(row.vehicle_id&&!source);
   save.textContent=source?(dest?.device_id?'Konfirmasi tukar GPS':'Konfirmasi pindah GPS'):'Hubungkan GPS';
   if(!dest)return;
   const from=vehicleIdentity(source||row)||'Belum terhubung',to=vehicleIdentity(dest);
   preview.append(el('strong','Sebelum'),el('span',gps+' → '+from),el('span',to+' → '+(dest.device_identifier||'Belum ada GPS')));
   if(save.disabled){preview.append(el('small','Pilih kendaraan tanpa GPS, atau muat ulang jika relasi baru berubah.'));return;}
   preview.append(el('strong','Sesudah'),el('span',gps+' → '+to));
   if(source)preview.append(el('span',dest.device_id?dest.device_identifier+' → '+from:from+' → Belum ada GPS'));
  };
  select.onchange=update;
  form.onsubmit=async event=>{
   event.preventDefault();
   const dest=target();
   if(!dest||(dest.device_id&&!source)||(row.vehicle_id&&!source))return;
   save.disabled=true;select.disabled=true;error.textContent='';
   const payload={vehicle_id:Number(dest.id)};
   if(source)payload.transfer={from_vehicle_id:Number(source.id),target_device_id:Number(dest.device_id||0)};
   try{await post('devices/'+row.id+'/connect-vehicle',payload);$('#inspector').close();await load();toast(source?'Relasi GPS diperbarui.':'GPS berhasil dihubungkan ke kendaraan.');}
   catch(e){error.textContent=e.message;}finally{select.disabled=false;update();}
  };
  inspect(row.vehicle_id?'Pindahkan atau tukar GPS':'Hubungkan kendaraan',form);
 }catch(e){toast(e.message);}
}
