async function exportVehicleRegistry(){const button=$$('#screen button').find(b=>/export|ekspor/i.test(buttonLabel(b)));if(button)button.disabled=true;try{const all=[];let next=null;const seen=new Set();do{const query=queryFor('vehicles');query.set('limit','200');query.delete('cursor');if(next)query.set('cursor',next);const result=await api('vehicles?'+query);all.push(...result.data);const value=result.page?.has_more?result.page.next_cursor:null;if(value&&seen.has(value))throw new Error('Pagination ekspor tidak maju. Silakan ulangi.');if(value)seen.add(value);next=value;}while(next);if(!all.length){toast('Belum ada kendaraan untuk diekspor.');return;}const keys=['plate_number','vehicle_name','fleet_code','device_model','device_identifier','movement_status','speed_kmh','physical_ignition_state','fuel_liters','fuel_percent','fuel_validity','sensor_status','ignition_status','ignition_source','ignition_reported_at','gps_time','device_last_received_at'];const quote=value=>'"'+String(value??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const csv=[keys,...all.map(row=>keys.map(key=>row[key]))].map(row=>row.map(quote).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));const link=el('a');link.href=url;link.download='vehicles-'+new Date().toISOString().slice(0,10)+'.csv';link.click();URL.revokeObjectURL(url);toast(all.length+' kendaraan diekspor sesuai filter.');}catch(error){toast(error.message);}finally{if(button)button.disabled=false;}}

function prepareVehicleOverview(){if(routeKey!=='vehicle-overview')return;const screen=$('#screen');screen.replaceChildren();screen.className='vehicle-overview-page';const header=el('header');header.append(el('h1','Telematics Overview'),el('p','Laporan terakhir GV30CEU dan CFS300B. Data lama tetap ditampilkan dengan waktu aslinya.'));const back=el('a','← Daftar kendaraan');back.href='#vehicles';header.prepend(back);screen.append(header);const identityPanel=el('section');identityPanel.dataset.overviewIdentity='';screen.append(identityPanel);const nav=el('nav');nav.className='overview-tabs';for(const[tab,title]of [['overview','Telematics Overview'],['trips','Trip History'],['fuel','Fuel & BLE'],['calibration','Kalibrasi'],['device','Device Info']]){const link=el('a',title);link.href='#vehicles/'+selectedVehicle+'/'+tab;if(tab==='overview')link.setAttribute('aria-current','page');nav.append(link);}screen.append(nav);const cards=el('div');cards.className='overview-metrics';for(const[key,title]of [['speed','Speed & Dynamics'],['fuel','Fuel CFS300B'],['gps','GPS Quality'],['gateway','Koneksi GV30CEU'],['sensor','Sensor BLE']]){const card=el('section');card.dataset.overviewMetric=key;card.append(el('h2',title),el('div'));cards.append(card);}screen.append(cards);const map=el('section');map.dataset.map='';map.className='stitch-map overview-map';screen.append(map);const more=el('section');more.className='overview-explanation';more.append(el('h2','Ketersediaan data'),el('p','Ignition fisik: NOT_INSTALLED. Status bergerak berasal dari kecepatan GPS, bukan bukti mesin hidup.'),el('p','RSSI, percepatan, tegangan, odometer, jenis konstelasi, konsumsi dan deteksi pencurian hanya dapat ditampilkan bila ada data/proses terverifikasi. Tidak diisi dengan angka contoh.'));screen.append(more);}
function updateVehicleOverview(){if(routeKey!=='vehicle-overview')return;const row=records.find(p=>String(p.id)===String(selectedVehicle));if(!row)return;const identity=$('#screen [data-overview-identity]');if(identity){identity.replaceChildren(el('h2',(row.plate_number||'Kendaraan')+' · '+(row.vehicle_name||'')),el('p','Fleet: '+(row.fleet_code||'Belum ditentukan')+' · GPS: '+(row.device_model||'Belum dihubungkan')+' '+(row.device_identifier||'')),el('p','Status: '+(row.movement_status||'Tidak tersedia')),ignitionIndicator(row),el('p','Ignition terakhir: '+date(row.ignition_reported_at)+(row.ignition_source?' · '+row.ignition_source:'')));}
 const values={speed:[['Kecepatan terakhir',row.speed_kmh==null?'Belum ada pengukuran':currentSpeed(row)],['Arah',num(row.heading_deg,'°')],['Waktu GPS',date(row.gps_time)],['Kesegaran',row.gps_fresh?'Terkini':'Data lama / belum tersedia']],fuel:[['Volume terkalibrasi',num(row.fuel_liters,'L')],['Level terkalibrasi',num(row.fuel_percent,'%')],['Validitas',detailValue('fuel_validity',row.fuel_validity)],['Diterima server',date(row.fuel_received_at)],['Kesegaran',row.fuel_fresh?'Terkini':'Data lama / waktu ukur belum tersedia']],gps:[['Fix laporan terakhir',row.fix_status||'Belum ada laporan'],['Satelit',num(row.satellite_count)],['HDOP',num(row.hdop)],['Koordinat',row.latitude==null?'Tidak tersedia':row.latitude+', '+row.longitude]],gateway:[['Koneksi sekarang',row.connectivity||'Belum terhubung'],['Gateway terakhir mengirim',date(row.device_last_received_at)],['Model',row.device_model||'Belum dihubungkan'],['Identitas',row.device_identifier||'Tidak tersedia']],sensor:[['Status laporan',detailValue('sensor_status',row.sensor_status)],['Sensor terakhir mengirim',date(row.sensor_last_received_at)],['Jalur data','CFS300B → GV30CEU → kendaraan'],['RSSI','Tidak tersedia pada laporan ini']]};for(const[key,fields]of Object.entries(values)){const body=$('#screen [data-overview-metric="'+key+'"] > div');if(!body)continue;for(const[index,[label,value]]of fields.entries()){let line=body.children[index];if(!line){line=el('div');line.append(el('span'),el('strong'));body.append(line);}if(line.firstElementChild.textContent!==label)line.firstElementChild.textContent=label;if(line.lastElementChild.textContent!==String(value))line.lastElementChild.textContent=value;}}}

function fuelReadingInfo(row){const panel=el('div');panel.className='dashboard-activity-detail';panel.append(el('h3',row.plate_number||'Pembacaan CFS300B'),detailFields({fuel_validity:row.fuel_validity,fuel_raw:row.fuel_raw,fuel_raw_min:row.fuel_raw_min,fuel_raw_max:row.fuel_raw_max,fuel_calibration_id:row.fuel_calibration_id,fuel_received_at:row.fuel_received_at}),el('p','Jika nilai raw berada di luar rentang Empty–Full, liter dan persen tidak dihitung. Status koneksi sensor terpisah dari validitas kalibrasi.','detail-note'));inspect('Detail pembacaan fuel',panel);}
