const remoteRequestedStates=new Map(),remoteSending=new Set();
async function remoteOutputDialog(row){
 const id=String(row.id);if(remoteSending.has(id))return;remoteSending.add(id);
 const controls=()=>$$('#screen [data-row-action=remote-output]').filter(b=>String(tableRows.get(b.closest('tr,[data-vehicle-card]'))?.row.id)===id);
 for(const button of controls()){button.disabled=true;button.textContent='Mengirim…';}
 try{
  const cap=(await api('vehicles/'+id+'/remote-output')).data;
  if(!cap.configured||!cap.connected)throw new Error(cap.reason||'GPS belum terhubung.');
  if(identity.role!=='admin')throw new Error('Kontrol mesin hanya tersedia untuk administrator.');
  const latest=tableRows.get(controls()[0]?.closest('tr,[data-vehicle-card]'))?.row||row;const pending=remoteRequestedStates.get(id);const desired=!(pending?.active??remoteState(latest,cap));
  const bytes=new Uint8Array(32);crypto.getRandomValues(bytes);const key=[...bytes].map(n=>n.toString(16).padStart(2,'0')).join('');
  const response=await post('vehicles/'+id+'/remote-output',{active:desired,request_key:key});
  if(response.data.state==='sent'||response.data.state==='acknowledged'){remoteRequestedStates.set(id,{active:desired,at:Date.now()});toast('Perintah '+(desired?'OFF':'ON')+' dikirim. Menunggu laporan perangkat.');}else toast('Status pengiriman: '+response.data.state+'. Periksa hasil sebelum mengirim lagi.');
 }catch(error){toast(error.message);}
 finally{remoteSending.delete(id);for(const button of controls()){button.disabled=false;updateRemoteButton(button,tableRows.get(button.closest('tr,[data-vehicle-card]'))?.row||row);}}
}

function prepareRemoteColumn(){if(routeKey!=='vehicles'&&routeKey!=='fleet-dashboard')return;const table=$('#screen table');const action=table&&[...table.querySelectorAll('th')].find(th=>/^actions?$/i.test(th.textContent.trim()));if(action&&!table.querySelector('[data-remote-column]')){const remote=el('th','Remote',action.className);remote.dataset.remoteColumn='';action.before(remote);}}
function showNotificationPopup(){const existing=$('#alert-notification-dropdown');if(existing){existing.remove();return;}api('alerts/events?limit=50').then(result=>{const rows=(result.data||[]).filter(row=>!['resolved','closed','false_positive'].includes(String(row.state||'').toLowerCase()));let menu=$('#alert-notification-dropdown');if(menu)menu.remove();menu=el('div');menu.id='alert-notification-dropdown';menu.className='alert-notification-dropdown';const head=el('div','Alert aktif','alert-notification-heading');menu.append(head);if(!rows.length)menu.append(el('div','Tidak ada alert aktif.','alert-notification-empty'));for(const row of rows.slice(0,12)){const item=el('button');item.type='button';item.className='alert-notification-item';item.append(el('strong',(row.plate_number||row.vehicle_name||'Kendaraan')+' · '+(row.title||row.rule_code)),el('span',String(row.severity||'WARNING')+' · '+date(row.raised_at)));item.onclick=()=>{menu.remove();location.hash='alert-center';setTimeout(()=>alertDetail(row),150);};menu.append(item);}const footer=el('button','Buka Alert Center →','alert-notification-footer');footer.onclick=()=>{menu.remove();location.hash='alert-center';};menu.append(footer);document.body.append(menu);}).catch(()=>toast('Alert belum dapat dimuat.'));}
document.addEventListener('click',event=>{const button=event.target.closest?.('#stitch-header [data-action=notifications]');if(button){event.preventDefault();event.stopImmediatePropagation();showNotificationPopup();}},true);
document.addEventListener('click',event=>{const menu=$('#alert-notification-dropdown');if(menu&&!event.target.closest('#alert-notification-dropdown')&&!event.target.closest('#stitch-header [data-action=notifications]'))menu.remove();},true);document.addEventListener('keydown',event=>{if(event.key==='Escape')$('#alert-notification-dropdown')?.remove();});
let alertAudioContext=null,alertSoundReady=false,alertNotificationIds=new Set();
function unlockAlertSound(){try{alertAudioContext??=new (window.AudioContext||window.webkitAudioContext)();if(alertAudioContext.state==='suspended')alertAudioContext.resume();alertSoundReady=true;}catch{}}
function playAlertSound(kind='CRASH'){if(!alertSoundReady||!alertAudioContext)return;const now=alertAudioContext.currentTime;const tones=kind==='FUEL_DROP'?[740,740,540,740,740,540]:[980,760,980,760,980,760];tones.forEach((frequency,index)=>{const oscillator=alertAudioContext.createOscillator(),gain=alertAudioContext.createGain();oscillator.type='square';oscillator.frequency.value=frequency;const start=now+index*.18;gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(.24,start+.015);gain.gain.exponentialRampToValueAtTime(.0001,start+.14);oscillator.connect(gain).connect(alertAudioContext.destination);oscillator.start(start);oscillator.stop(start+.15);});}
document.addEventListener('pointerdown',unlockAlertSound,{once:false,passive:true});
